result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

spm_by_ticker = Transactions.WHERE(
    (LOWER(transaction_type) == 'sell') &
    (date_time >= DATETIME('now', '-1 month'))
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    total_sell_amount=SUM(Transactions.amount),
    total_costs=SUM(Transactions.tax + Transactions.commission)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    spm=IFF(
        total_sell_amount > 0,
        (total_sell_amount - total_costs) * 100.0 / total_sell_amount,
        0.0
    )
)

monthly_active_senders = Ewallet.Transactions.WHERE(
    (YEAR(created_at) == 2023) &
    (LOWER(status) == 'completed') &
    (LOWER(sender_type) == 'user') &
    (LOWER(sending_user.status) == 'active')
).CALCULATE(
    year_month_key=JOIN_STRINGS('-', YEAR(created_at), LPAD(MONTH(created_at), 2, '0'))
).PARTITION(
    name="monthly_groups", by=year_month_key
).CALCULATE(
    month=year_month_key,
    num_active_users=NDISTINCT(Transactions.sending_user.uid)
).ORDER_BY(month.ASC())

